"""Multiple-choice assessments: generated by the AI model from the notes, or drawn from the offline bank.

An assessment can mix several subjects, has 3-30 questions, a difficulty (or a mix), and one of
three modes: practice (feedback after every question), exam (feedback at the end) and timed
(exam with a countdown)."""

import json
import logging
import random
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

from . import gamification, knowledge, languages
from .ai import AIService, AIUnavailable
from .db import now_iso
from .translation import TranslationError, Translator

log = logging.getLogger(__name__)

DIFFICULTIES = {"easy", "medium", "hard", "mixed"}
MODES = {"practice", "exam", "timed"}
MIN_QUESTIONS, MAX_QUESTIONS = 3, 30
SECONDS_PER_QUESTION = {"easy": 45, "medium": 60, "hard": 90, "mixed": 60}
BATCH_SIZE = 5

QUIZ_PROMPT = """You write multiple-choice quizzes for school students in India, based on the school's \
study notes below. Every question must be answerable from the notes, have exactly four options with exactly \
one correct answer, and avoid "all of the above" style options. Vary which option position is correct. \
Explanations are one or two encouraging sentences that teach why the answer is right. Don't use emoji. Write maths with \
LaTeX between $...$.

Reply with JSON only, in exactly this shape:
{"questions": [{"question": "...", "options": ["...", "...", "...", "..."], "answer_index": 0, "explanation": "..."}]}
where answer_index is the 0-based position of the correct option."""


class QuizError(Exception):
    pass


def _valid(question: dict) -> bool:
    options = question.get("options")
    return (
        isinstance(question.get("question"), str) and question["question"].strip()
        and isinstance(options, list) and len(options) == 4 and all(isinstance(o, str) and o.strip() for o in options)
        and isinstance(question.get("answer_index"), int) and 0 <= question["answer_index"] < 4
        and isinstance(question.get("explanation"), str)
    )


def _shuffle_options(question: dict) -> dict:
    order = list(range(4))
    random.shuffle(order)
    return {**question, "options": [question["options"][i] for i in order],
            "answer_index": order.index(question["answer_index"])}


def _split(count: int, parts: int) -> list[int]:
    """Spread `count` questions as evenly as possible over `parts` subjects."""
    base, extra = divmod(count, parts)
    return [base + (1 if i < extra else 0) for i in range(parts)]


class QuizMaster:
    def __init__(self, ai: AIService, translator: Translator, content_dir: Path):
        self.ai = ai
        self.translator = translator
        self.bank_dir = content_dir / "quizzes"

    # ------------------------------------------------------------------ question sources

    def _generate_ai(self, doc: dict, topic: str, count: int, difficulty: str, language: str) -> list[dict]:
        system = f'{QUIZ_PROMPT}\n\n<notes title="{doc["title"]}">\n{doc["body"]}\n</notes>'
        native = languages.LANGUAGES[language][1]
        focus = f"Focus on: {topic}." if topic else "Cover a mix of topics from across the notes."
        level = "questions of mixed difficulty (some easy, some medium, some hard)" if difficulty == "mixed" else f"{difficulty} questions"
        prompt = (
            f"Write {count} {level} for the {doc['title']} quiz. {focus} "
            f"Write the questions, options and explanations in {languages.english_name(language)} ({native})."
        )
        data = self.ai.generate_json(system, prompt, max_tokens=min(8000, 600 + 350 * count))
        questions = [q for q in data.get("questions", []) if _valid(q)]
        if len(questions) < min(count, 3):
            raise AIUnavailable("The model returned too few valid questions")
        return questions[:count]

    def _bank(self, slug: str) -> list[dict]:
        path = self.bank_dir / f"{slug}.json"
        if not path.exists():
            return []
        return [q for q in json.loads(path.read_text(encoding="utf-8")) if _valid(q)]

    def _generate_offline(self, slug: str, topic: str, count: int, difficulty: str) -> list[dict]:
        bank = self._bank(slug)
        if not bank:
            return []
        pool = bank if difficulty == "mixed" else ([q for q in bank if q.get("difficulty", "medium") == difficulty] or bank)
        if topic:
            words = set(knowledge.tokenize(topic))
            matching = [q for q in pool if words & set(knowledge.tokenize(q["question"] + " " + q.get("topic", "")))]
            pool = matching or pool
        if len(pool) < count:
            pool = pool + [q for q in bank if q not in pool]
        chosen = random.sample(pool, min(count, len(pool)))
        return [_shuffle_options({k: q[k] for k in ("question", "options", "answer_index", "explanation")}) for q in chosen]

    def _translate(self, questions: list[dict], language: str) -> list[dict]:
        strings = []
        for q in questions:
            strings.extend([q["question"], *q["options"], q["explanation"]])

        def one(text: str) -> str:
            try:
                return self.translator.translate(text, language, "en")[0]
            except TranslationError:
                return text

        with ThreadPoolExecutor(max_workers=8) as pool:
            translated = iter(list(pool.map(one, strings)))
        return [
            {**q, "question": next(translated), "options": [next(translated) for _ in range(4)],
             "explanation": next(translated)}
            for q in questions
        ]

    def _questions_for(self, doc: dict, topic: str, count: int, difficulty: str, language: str) -> tuple[list[dict], str]:
        if self.ai.available:
            try:
                return self._generate_ai(doc, topic, count, difficulty, language), "ai"
            except AIUnavailable as exc:
                log.warning("AI questions unavailable for %s, using the question bank: %s", doc["slug"], exc)
        questions = self._generate_offline(doc["slug"], topic, count, difficulty)
        if questions and language != "en":
            questions = self._translate(questions, language)
        return questions, "library"

    # ------------------------------------------------------------------ public API

    def create(self, conn, user, subjects: list[str], topic: str, count: int, difficulty: str,
               language: str, mode: str = "practice") -> dict:
        slugs = list(dict.fromkeys(s for s in subjects if isinstance(s, str)))[:8]
        docs = [knowledge.get_document(conn, s) for s in slugs]
        if not docs or any(d is None or d["kind"] != "subject" for d in docs):
            raise QuizError("Choose at least one subject")
        if not isinstance(count, int):
            count = 10
        count = max(MIN_QUESTIONS, min(MAX_QUESTIONS, count, ))
        if difficulty not in DIFFICULTIES:
            difficulty = "medium"
        if mode not in MODES:
            mode = "practice"
        topic = topic.strip()[:80]

        def build(args):
            doc, n, focus = args
            questions, engine = self._questions_for(doc, focus or topic, n, difficulty, language)
            return [{**q, "subject": doc["slug"], "subject_title": doc["title"]} for q in questions], engine

        jobs = []
        for doc, n in zip(docs, _split(count, len(docs))):
            if n <= 0:
                continue
            if self.ai.available and n > BATCH_SIZE and not topic:
                # Write long assessments as parallel batches of 5, each on different chapters,
                # so they finish in roughly the time of one short batch without repeating questions.
                batches = -(-n // BATCH_SIZE)
                chapters = [line[3:].strip() for line in doc["body"].splitlines() if line.startswith("## ")]
                for i, size in enumerate(_split(n, batches)):
                    picked = chapters[i::batches]
                    jobs.append((doc, size, ", ".join(picked) if picked else ""))
            else:
                jobs.append((doc, n, ""))
        with ThreadPoolExecutor(max_workers=6) as pool:
            results = list(pool.map(build, jobs))
        questions = [q for qs, _ in results for q in qs]
        engines = {engine for qs, engine in results if qs}
        if not questions:
            raise QuizError("No questions are available for these subjects yet")
        if len(docs) > 1:
            random.shuffle(questions)  # interleave subjects

        notice = None
        if len(questions) < count:
            notice = (f"Only {len(questions)} questions are available offline for this selection. "
                      "Add a free NVIDIA API key in the teacher console for unlimited AI-written questions.")
        time_limit = SECONDS_PER_QUESTION[difficulty] * len(questions) if mode == "timed" else None
        engine = "ai" if engines == {"ai"} else ("mixed" if "ai" in engines else "library")

        cur = conn.execute(
            """INSERT INTO quizzes (user_id, subject, subjects_json, topic, language, difficulty, questions_json,
                                    answers_json, total, engine, mode, time_limit, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, '{}', ?, ?, ?, ?, ?)""",
            (user["id"], slugs[0] if len(slugs) == 1 else "mixed", json.dumps(slugs), topic or None, language,
             difficulty, json.dumps(questions, ensure_ascii=False), len(questions), engine, mode, time_limit, now_iso()),
        )
        conn.commit()
        return self._public(cur.lastrowid, docs, topic, difficulty, mode, time_limit, engine, questions, notice)

    @staticmethod
    def _public(quiz_id, docs, topic, difficulty, mode, time_limit, engine, questions, notice=None) -> dict:
        return {
            "id": quiz_id,
            "subjects": [{"slug": d["slug"], "title": d["title"], "color": d["color"]} for d in docs],
            "subject": docs[0]["slug"] if len(docs) == 1 else "mixed",
            "subject_title": docs[0]["title"] if len(docs) == 1 else " + ".join(d["title"] for d in docs),
            "topic": topic,
            "difficulty": difficulty,
            "mode": mode,
            "time_limit": time_limit,
            "engine": engine,
            "notice": notice,
            "questions": [{"question": q["question"], "options": q["options"], "subject": q.get("subject"),
                           "subject_title": q.get("subject_title")} for q in questions],
        }

    def _load(self, conn, user, quiz_id: int):
        quiz = conn.execute("SELECT * FROM quizzes WHERE id = ? AND user_id = ?", (quiz_id, user["id"])).fetchone()
        if quiz is None:
            raise QuizError("Quiz not found")
        if quiz["completed_at"]:
            raise QuizError("This assessment is already finished")
        return quiz, json.loads(quiz["questions_json"])

    def _finish(self, conn, user, quiz, questions: list[dict], answers: dict, duration_s: int | None) -> dict:
        score = sum(1 for i, q in enumerate(questions) if answers.get(str(i)) == q["answer_index"])
        conn.execute(
            "UPDATE quizzes SET answers_json = ?, score = ?, completed_at = ?, duration_s = ? WHERE id = ?",
            (json.dumps(answers), score, now_iso(), duration_s, quiz["id"]),
        )
        reward = gamification.record_quiz(conn, user["id"], score, len(questions), quiz["mode"] or "practice")
        xp_total = conn.execute("SELECT xp FROM users WHERE id = ?", (user["id"],)).fetchone()["xp"]

        breakdown: dict[str, dict] = {}
        for i, q in enumerate(questions):
            entry = breakdown.setdefault(q.get("subject") or "", {"subject": q.get("subject_title") or "", "correct": 0, "total": 0})
            entry["total"] += 1
            entry["correct"] += answers.get(str(i)) == q["answer_index"]
        return {
            "score": score,
            "total": len(questions),
            "duration_s": duration_s,
            "breakdown": list(breakdown.values()),
            "xp_gained": reward["xp"],
            "badges": reward["badges"],
            "level_up": reward["level_up"],
            "goal": reward["goal"],
            "progress": gamification.level_info(xp_total),
        }

    def answer(self, conn, user, quiz_id: int, index: int, choice: int, duration_s: int | None = None) -> dict:
        """Practice mode: grade one question immediately; finishes the quiz on the last answer."""
        quiz, questions = self._load(conn, user, quiz_id)
        answers = json.loads(quiz["answers_json"] or "{}")
        if not (0 <= index < len(questions)) or not (0 <= choice < 4):
            raise QuizError("Invalid answer")
        if str(index) in answers:
            raise QuizError("You already answered this question")

        question = questions[index]
        answers[str(index)] = choice
        result = {
            "correct": choice == question["answer_index"],
            "answer_index": question["answer_index"],
            "explanation": question["explanation"],
        }
        conn.execute("UPDATE quizzes SET answers_json = ? WHERE id = ?", (json.dumps(answers), quiz_id))
        if len(answers) == len(questions):
            result["finished"] = self._finish(conn, user, quiz, questions, answers, duration_s)
        conn.commit()
        return result

    def submit(self, conn, user, quiz_id: int, choices: list, duration_s: int | None = None) -> dict:
        """Exam and timed modes: grade every answer at once. Unanswered questions (None) count as wrong."""
        quiz, questions = self._load(conn, user, quiz_id)
        if not isinstance(choices, list) or len(choices) != len(questions):
            raise QuizError("Send one answer (or null) per question")
        answers = {}
        for i, choice in enumerate(choices):
            if choice is None:
                continue
            if not isinstance(choice, int) or not 0 <= choice < 4:
                raise QuizError("Invalid answer")
            answers[str(i)] = choice
        finished = self._finish(conn, user, quiz, questions, answers, duration_s)
        conn.commit()
        finished["results"] = [
            {"choice": answers.get(str(i)), "correct": answers.get(str(i)) == q["answer_index"],
             "answer_index": q["answer_index"], "explanation": q["explanation"]}
            for i, q in enumerate(questions)
        ]
        return finished

    def retry_mistakes(self, conn, user, quiz_id: int) -> dict:
        """A new practice assessment made of the questions answered wrongly (or skipped) last time."""
        quiz = conn.execute("SELECT * FROM quizzes WHERE id = ? AND user_id = ?", (quiz_id, user["id"])).fetchone()
        if quiz is None:
            raise QuizError("Quiz not found")
        if not quiz["completed_at"]:
            raise QuizError("Finish this assessment first")
        questions = json.loads(quiz["questions_json"])
        answers = json.loads(quiz["answers_json"] or "{}")
        wrong = [_shuffle_options(q) for i, q in enumerate(questions) if answers.get(str(i)) != q["answer_index"]]
        if not wrong:
            raise QuizError("You got everything right, so there's nothing to retry")
        random.shuffle(wrong)
        slugs = json.loads(quiz["subjects_json"]) if quiz["subjects_json"] else [quiz["subject"]]
        docs = [d for d in (knowledge.get_document(conn, s) for s in slugs) if d]
        cur = conn.execute(
            """INSERT INTO quizzes (user_id, subject, subjects_json, topic, language, difficulty, questions_json,
                                    answers_json, total, engine, mode, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, '{}', ?, ?, 'practice', ?)""",
            (user["id"], quiz["subject"], quiz["subjects_json"], "Retry: mistakes", quiz["language"], quiz["difficulty"],
             json.dumps(wrong, ensure_ascii=False), len(wrong), quiz["engine"], now_iso()),
        )
        conn.commit()
        return self._public(cur.lastrowid, docs, "Retry: mistakes", quiz["difficulty"], "practice", None, quiz["engine"], wrong)

    # ------------------------------------------------------------------ history

    def history(self, conn, user, limit: int = 200) -> list[dict]:
        titles = {r["slug"]: (r["title"], r["color"]) for r in conn.execute("SELECT slug, title, color FROM documents")}
        rows = conn.execute(
            """SELECT id, subject, subjects_json, topic, mode, difficulty, total, score, engine, language,
                      created_at, completed_at, duration_s, answers_json
               FROM quizzes WHERE user_id = ? ORDER BY id DESC LIMIT ?""",
            (user["id"], limit),
        ).fetchall()
        out = []
        for r in rows:
            slugs = json.loads(r["subjects_json"]) if r["subjects_json"] else [r["subject"]]
            out.append({
                "id": r["id"], "topic": r["topic"], "mode": r["mode"] or "practice", "difficulty": r["difficulty"],
                "total": r["total"], "score": r["score"], "engine": r["engine"], "language": r["language"],
                "created_at": r["created_at"], "completed_at": r["completed_at"], "duration_s": r["duration_s"],
                "answered": len(json.loads(r["answers_json"] or "{}")),
                "subjects": [{"slug": s, "title": titles.get(s, (s, ""))[0], "color": titles.get(s, ("", "#0f5a57"))[1]}
                             for s in slugs],
            })
        return out

    def detail(self, conn, user, quiz_id: int) -> dict:
        """A past assessment. Finished ones include the answers, results and breakdown for review."""
        quiz = conn.execute("SELECT * FROM quizzes WHERE id = ? AND user_id = ?", (quiz_id, user["id"])).fetchone()
        if quiz is None:
            raise QuizError("Quiz not found")
        questions = json.loads(quiz["questions_json"])
        slugs = json.loads(quiz["subjects_json"]) if quiz["subjects_json"] else [quiz["subject"]]
        docs = [d for d in (knowledge.get_document(conn, s) for s in slugs) if d]
        public = self._public(quiz["id"], docs, quiz["topic"] or "", quiz["difficulty"], quiz["mode"] or "practice",
                              quiz["time_limit"], quiz["engine"], questions)
        public.update(created_at=quiz["created_at"], completed_at=quiz["completed_at"], language=quiz["language"])
        if quiz["completed_at"]:
            answers = json.loads(quiz["answers_json"] or "{}")
            breakdown: dict[str, dict] = {}
            for i, q in enumerate(questions):
                entry = breakdown.setdefault(q.get("subject") or "", {"subject": q.get("subject_title") or "", "correct": 0, "total": 0})
                entry["total"] += 1
                entry["correct"] += answers.get(str(i)) == q["answer_index"]
            public["finished"] = {
                "score": quiz["score"], "total": quiz["total"], "duration_s": quiz["duration_s"],
                "breakdown": list(breakdown.values()),
                "results": [{"choice": answers.get(str(i)), "correct": answers.get(str(i)) == q["answer_index"],
                             "answer_index": q["answer_index"], "explanation": q["explanation"]}
                            for i, q in enumerate(questions)],
            }
        return public

    def retake(self, conn, user, quiz_id: int) -> dict:
        """Take a past assessment again: the same questions, with questions and options reshuffled."""
        quiz = conn.execute("SELECT * FROM quizzes WHERE id = ? AND user_id = ?", (quiz_id, user["id"])).fetchone()
        if quiz is None:
            raise QuizError("Quiz not found")
        questions = [_shuffle_options(q) for q in json.loads(quiz["questions_json"])]
        random.shuffle(questions)
        slugs = json.loads(quiz["subjects_json"]) if quiz["subjects_json"] else [quiz["subject"]]
        docs = [d for d in (knowledge.get_document(conn, s) for s in slugs) if d]
        mode = quiz["mode"] or "practice"
        cur = conn.execute(
            """INSERT INTO quizzes (user_id, subject, subjects_json, topic, language, difficulty, questions_json,
                                    answers_json, total, engine, mode, time_limit, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, '{}', ?, ?, ?, ?, ?)""",
            (user["id"], quiz["subject"], quiz["subjects_json"], quiz["topic"], quiz["language"], quiz["difficulty"],
             json.dumps(questions, ensure_ascii=False), len(questions), quiz["engine"], mode, quiz["time_limit"], now_iso()),
        )
        conn.commit()
        return self._public(cur.lastrowid, docs, quiz["topic"] or "", quiz["difficulty"], mode, quiz["time_limit"],
                            quiz["engine"], questions)

    def delete(self, conn, user, quiz_id: int) -> None:
        cur = conn.execute("DELETE FROM quizzes WHERE id = ? AND user_id = ?", (quiz_id, user["id"]))
        if not cur.rowcount:
            raise QuizError("Quiz not found")
        conn.commit()
